    "B60R21/00\\": {
      "code": "B60R21/00\\",
      "level": 0,
      "parent": null,
      "ja": "事故又は他の交通危機の場合乗員又は歩行者を負傷から保護又は防止するための車両の装置又は部品（車両における安全ベルトまたは身体用設備Ｂ６０Ｒ２２／００；異常加速度による影響から乗っている人間を保護する様，特に設計された座席，例．安全座席，Ｂ６０Ｎ２／４２；車両操向用ハンドホイールエネルギー吸収装置Ｂ６２Ｄ１／１１；車両操向用コラムエネルギー吸収装置Ｂ６２Ｄ１／１９）［４，５］",
      "en": "Arrangements or fittings on vehicles for protecting or preventing injuries to occupants or pedestrians in case of accidents or other traffic risks (safety belts or body harnesses in vehicles B60R 22/00; seats constructed to protect the occupant from the effect of abnormal g-forces, e.g. crash or safety seats, B60N 2/42; energy-absorbing arrangements for hand wheels for steering vehicles B62D 1/11; energy-absorbing arrangements for vehicle steering columns B62D 1/19) [4,5]",
      "count": 540,
      "ipcCode": "B60R21/00",
      "fTerm": "3D017",
      "childFlag": 0,
      "sourceFile": "fi_B60R.txt",
      "kind": "fi"
    },
